const require_runtime = require('./_virtual/_rolldown/runtime.cjs');
const require_logger = require('./logger.cjs');
const require_telemetry = require('./telemetry.cjs');
const require_pool_config = require('./pool-config.cjs');
let pg = require("pg");
pg = require_runtime.__toESM(pg);
let _opentelemetry_api = require("@opentelemetry/api");

//#region src/pool.ts
/**
* Create a PostgreSQL connection pool with automatic OAuth token refresh for Lakebase.
*
* This function returns a standard `pg.Pool` instance configured with a password callback
* that automatically fetches and caches OAuth tokens from Databricks. The returned pool
* works with any ORM or library that accepts a `pg.Pool` (Drizzle, Prisma, TypeORM, etc.).
*
* @param config - Configuration options (optional, reads from environment if not provided)
* @returns Standard pg.Pool instance with OAuth token refresh
*
* @see https://docs.databricks.com/aws/en/oltp/projects/authentication
*
* @example Using environment variables
* ```typescript
* // Set: PGHOST, PGDATABASE, LAKEBASE_ENDPOINT
* const pool = createLakebasePool();
* const result = await pool.query('SELECT * FROM users');
* ```
*
* @example With explicit configuration
* ```typescript
* // Use the `name` field from the Databricks CLI output:
* // `databricks postgres list-endpoints projects/{project-id}/branches/{branch-id}`
* const pool = createLakebasePool({
*   endpoint: 'projects/{project-id}/branches/{branch-id}/endpoints/{endpoint-identifier}',
*   host: 'ep-abc.databricks.com',
*   database: 'databricks_postgres',
*   user: 'service-principal-id'
* });
* ```
*
* @example With Drizzle ORM
* ```typescript
* import { drizzle } from 'drizzle-orm/node-postgres';
* const pool = createLakebasePool();
* const db = drizzle({ client: pool });
* ```
*
* @example With Prisma
* ```typescript
* import { PrismaPg } from '@prisma/adapter-pg';
* const pool = createLakebasePool();
* const adapter = new PrismaPg(pool);
* const prisma = new PrismaClient({ adapter });
* ```
*/
function createLakebasePool(config) {
	const userConfig = config ?? {};
	const logger = require_logger.resolveLogger(userConfig.logger);
	const telemetry = require_telemetry.initTelemetry();
	const poolConfig = require_pool_config.getLakebasePgConfig(userConfig, telemetry, logger);
	const pool = new pg.default.Pool(poolConfig);
	require_telemetry.attachPoolMetrics(pool, telemetry, logger);
	const origQuery = pool.query.bind(pool);
	const tracer = telemetry.tracer;
	pool.query = function queryWithTelemetry(...args) {
		const firstArg = args[0];
		const sql = typeof firstArg === "string" ? firstArg : firstArg?.text;
		const metricAttrs = { "db.statement": sql ? sql.substring(0, 100) : "unknown" };
		return tracer.startActiveSpan("lakebase.query", {
			kind: _opentelemetry_api.SpanKind.CLIENT,
			attributes: {
				"db.system": "lakebase",
				"db.user": poolConfig.user ?? "unknown",
				"db.statement": sql ? sql.substring(0, 500) : "unknown"
			}
		}, (span) => {
			const start = Date.now();
			const result = origQuery(...args);
			if (result && typeof result.then === "function") return result.then((res) => {
				span.setAttribute("db.rows_affected", res?.rowCount ?? 0);
				span.setStatus({ code: _opentelemetry_api.SpanStatusCode.OK });
				return res;
			}, (err) => {
				span.recordException(err);
				span.setStatus({ code: _opentelemetry_api.SpanStatusCode.ERROR });
				throw err;
			}).finally(() => {
				telemetry.queryDuration.record(Date.now() - start, metricAttrs);
				span.end();
			});
			telemetry.queryDuration.record(Date.now() - start, metricAttrs);
			span.end();
			return result;
		});
	};
	logger?.debug("Created Lakebase connection pool for %s@%s/%s", poolConfig.user, poolConfig.host, poolConfig.database);
	return pool;
}

//#endregion
exports.createLakebasePool = createLakebasePool;